do $$ begin if current_database()<>'superior_workflow_test' then raise exception 'Refusing non-disposable database'; end if; end $$;
begin;
create schema if not exists test_mixed;
create function test_mixed.assert(ok boolean,label text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception 'ASSERT FAILED: %',label; end if; raise notice 'PASS: %',label; end $$;
create function test_mixed.rejects(statement text,label text) returns void language plpgsql as $$ declare failed boolean:=false; begin begin execute statement; exception when others then failed:=true; end; perform test_mixed.assert(failed,label); end $$;
create function test_mixed.rejects_like(statement text,fragment text,label text) returns void language plpgsql as $$ declare caught text; begin begin execute statement; exception when others then caught:=sqlerrm; end; perform test_mixed.assert(caught is not null and position(fragment in caught)>0,label||coalesce(' ['||caught||']','')); end $$;
grant usage on schema test_mixed to authenticated;
grant execute on all functions in schema test_mixed to authenticated;
