 perform test_mixed.assert(not public.can_read_full_walls_production(),'operational editor still denied raw production tables');
 foreach p in array array['view','setup','pour','strip','issue','assign','plan'] loop perform test_mixed.assert(public.walls_production_permission(p),'production capability '||p); end loop;
 perform test_mixed.assert(public.walls_installation_permission('view') and public.walls_installation_permission('qc'),'field view and Walls QC allowed');
 foreach p in array array['manage','resources','field_progress'] loop perform test_mixed.assert(not public.walls_installation_permission(p),'field mutation denied '||p); end loop;
 x:=public.get_app_access();perform test_mixed.assert(x->>'profile_key'='walls_production_inventory_qc_v1' and jsonb_array_length(x->'allowed_views')=9 and not(x->'allowed_views' ? 'billing') and (x->'allowed_views' ? 'weekly-planner') and not public.weekly_planner_permission('view'),'exact mixed navigation without management/planner');
 x:=public.get_schedule_snapshot(); perform test_mixed.assert(jsonb_array_length(x#>'{payload,data,jobs}')=4,'only four authorized product divisions');perform test_mixed.assert(x::text not like '%SECRET_%' and x::text not like '%wrong-untrusted%','other division read projection strips private fields and authoritative division wins');
 perform test_mixed.assert(x#>'{payload,data,billing}'='[]' and x#>'{payload,data,qcHistory}'='[]' and x#>'{payload,data,loads}'='[]','billing other-division QC and delivery remain inaccessible');
 perform test_mixed.rejects('select public.save_schedule_snapshot(1,''{}''::jsonb)','global snapshot write denied');
