 perform test_mixed.assert((select count(*)=0 from public.walls_installation_qc_releases),'raw QC actor identities denied');
 x:=public.get_walls_production_snapshot(); perform test_mixed.assert(x::text not like '%SECRET_%','production projection strips raw private notes');
