 row:=public.upsert_walls_production_assignment(aid,'TEST-MIXED-WALL','TEST-MIXED-T2',8,40,current_date+time '08:00',current_date+time '16:00',current_date+1+time '08:00','Synthetic reschedule',(row->>'version')::bigint);
 perform test_mixed.assert(row->>'notes'='Synthetic reschedule','production assignment edit');
 row:=public.advance_walls_production_stage(aid,'setup_in_progress',1);
 row:=public.update_walls_production_setup_progress(aid,50,'Synthetic setup edit');perform test_mixed.assert((row->>'setup_progress')::int=50,'Today setup edit');
 row:=public.report_walls_production_issue(aid,'Drawing questions','Synthetic hold evidence');issue:=(row->>'issue_id')::bigint;
 perform test_mixed.rejects(format('select public.advance_walls_production_stage(%L::uuid,''setup_complete'')',aid),'production holds still block completion');
 row:=public.resolve_walls_production_issue(issue,'Synthetic issue resolved');perform test_mixed.assert(row->>'status'='resolved','production issue report and resolve');
 row:=public.advance_walls_production_stage(aid,'setup_complete');
 row:=public.advance_walls_production_stage(aid,'ready_for_pour',null,null,true,'Synthetic pre-pour checked');
 row:=public.advance_walls_production_stage(aid,'poured',null,40,true,'Synthetic pour');perform test_mixed.assert(row->>'stage'='poured','production pour edit');
 perform test_mixed.rejects(format('select public.set_walls_installation_qc(%L::uuid,''released'')',aid),'Walls final QC cannot precede strip');
 row:=public.advance_walls_production_stage(aid,'curing');row:=public.advance_walls_production_stage(aid,'stripped');perform test_mixed.assert(row->>'stage'='stripped','production strip edit');
 row:=public.capture_walls_production_weekly_forecast(current_date,'manual');perform test_mixed.assert(row?'week_start' and not(row?'created_by'),'weekly forecast edit safe return');
