 x:=public.set_walls_installation_qc('00000000-0000-4000-8100-000000000801','hold','Synthetic QC hold');perform test_mixed.assert(x->>'status'='hold' and not(x?'updated_by'),'Walls QC hold has safe mutation result');
 x:=public.set_walls_installation_qc('00000000-0000-4000-8100-000000000801','pending','Synthetic hold cleared');perform test_mixed.assert(x->>'status'='pending','Walls QC hold clears');
 x:=public.set_walls_installation_qc('00000000-0000-4000-8100-000000000801','released','Synthetic inspection verified');perform test_mixed.assert(x->>'status'='released' and not(x?'released_by_email'),'Walls QC release remains distinct and safe');
 perform test_mixed.rejects('select public.set_walls_installation_qc(''00000000-0000-4000-8100-000000000801'',''hold'','''')','QC hold requires evidence');
 for scope in select * from (values('walls','production'),('walls','install'),('boxes','production')) s(d,a) loop
  perform test_mixed.assert(public.inventory_scope_access(scope.d,scope.a,'manage'),'full inventory manage '||scope.d||'/'||scope.a);
  x:=public.get_inventory_snapshot(scope.d,scope.a);select v into row from jsonb_array_elements(x->'items') v where v->>'titan_code' like 'TEST-MIXED-%';
  row:=public.set_inventory_item((row->>'item_id')::bigint,(row->>'version')::bigint,9,3,'pieces');
  row:=public.mark_inventory_ordered((row->>'item_id')::bigint,(row->>'version')::bigint);
  row:=public.receive_inventory_stock((row->>'item_id')::bigint,(row->>'version')::bigint,5);
  perform test_mixed.assert((row->>'quantity')::int=14 and not(row?'updated_by'),'inventory manage mutation returns safe quantity '||scope.d||'/'||scope.a);
 end loop;
 perform test_mixed.assert(not public.inventory_scope_access('fence','production','manage'),'unlisted inventory scope denied');
end $$;
